#      而各版本升級預設值後從未遷移已儲存設定 → 用家看到的「預設」永遠是
#      舊值。修復：加入設定檔 schema 版本標記 (v10_schema)，載入時發現
#      舊快照即自動重置為目前最佳預設並立即回寫雲端 (強制寫入，繞過合併
#      保護)，日後升級預設值只需 bump schema。
