#      一方自動停止，不會重複寫入；手動模式 (輪次/日期) 完全不受影響。
#
#   限制 (如實說明)：Streamlit Community Cloud 沒有伺服器端排程 — 排程由
#   開啟著的分頁驅動 (背景 fragment 每 5 分鐘檢查)。保持至少一部裝置的
#   分頁開啟即可；若 09:30 時全部分頁關閉，下次開啟程式時會立即補跑。
#
#   風險評估：零。新功能在「排程觸發層」— 觸發的仍是 V15.10 日期模式自動
