# V15.8 LR 落注閘門 (凍結邏輯回歸模型 — 前向驗證中，不會自動重訓)
#
#   背景 (2026-11-15)：2,863 注全量覆盤 — 系統整體命中率 50.4% (打和線 52.6%)、
#   每注 −0.050 單位 (統計顯著)。「讓球高賠率優勢」不顯著 (p=0.18) 且 11/9 後
#   逆轉為負；角球盤顯著虧損 (已另設停用開關)。以 14 個特徵 (去水市場概率、
#   評分差、排名差、場均積分差、休息天數差、14日場數差、線移動、盤口類型等)
#   重建的邏輯回歸模型，在嚴格樣本外滾動測試 (每週重訓) 4/4 週 Brier score
#   皆優於市場基準 (0.2333→0.2273, p=0.01)；其中「讓球 + 模型概率高於去水
#   市場概率 2%」子集在 11/08-14 測試窗口 +0.114/注 (n=46)。
#
#   V15.8 內容：
#   1. 凍結邏輯回歸模型 (訓練數據 2026-10-05~11-14 全量, n=2,693) 以純 Python
#      內嵌 — 不需新增 sklearn 相依套件，Streamlit Cloud 免費層 requirements.txt
#      維持不變。係數、特徵工程、2% 門檻全部凍結，與前向驗證追蹤器
#      (forward_tracker.py) 完全一致；前向驗證結束前不會重訓，事後調整會令
#      驗證失效。
#   2. 每張注單寫入時計算並記錄四個新欄位：Model_Prob (模型概率)、
#      Market_Prob (去水市場概率)、Edge (兩者差距)、Gate (Y=通過 / N=攔截 /
#      -=無法計算)。所有注單照常記錄 — 學習、結算、分析路徑零改動，
#      前向驗證的對照組 (全部讓球注) 完整保留。
#   3. 閘門 (預設開啟，側邊欄可關)：Bet_Type=讓球 且 Edge ≤ 2% 時，系統注碼
#      強制 $0 (只作記錄供學習，不實注)；Edge > 2% 的讓球注照常實注。
#      非讓球盤口不受影響。門檻 2% 為預先登記值，前向驗證期間不可調整。
#
# ==============================================================================
# V15.7 自動輸入可靠性修復 (超時保護 + 例外續傳 + 跨裝置一鍵接手)
#
#   背景 (2026-11-14/15)：挪威超級聯賽第 18-26 輪自動輸入 (66 場) 反覆「靜默中斷」—
#   進度顯示「逾 5 分鐘無更新」，佇列後面的比賽整批沒被處理，重啟又死在別處，
#   累積成「很多場無法自動輸入」。V15.4 (Tipsme API 容錯) 及 V15.5 (模擬注預選)
#   已修好「填不到數據」與「空注項跳過」兩類問題；V15.7 修的是最後一類：
#   「運行中途死亡」。三個根因與對應修復：
#
#   根因 1 — GitHub 雲端同步無超時：load_db_github / save_db_github 的
#   requests.get/put 沒有 timeout，而自動模式下每個步驟 (寫注單/結算/進度同步)
#   都會呼叫它 (每場約 4-8 次 GitHub API)。只要一次請求卡住，整個腳本無限期
#   凍結 — 不報錯、不逾時，正是「更新到一半後完全靜默」的特徵。
#   修復 1 — _gh_request 統一 15 秒超時 + 重試一次；仍失敗回傳 None，
#   由既有 try/except 按原邏輯處理 (本地檔案後備 / 下次同步補上)，行為不變。
#
#   根因 2 — 四個關鍵步驟 (分析/投注/讀賽果/結算) 的按鈕分支無例外保護：
#   個別比賽數據觸發未預期例外時，整個腳本崩潰，自動輸入靜默死亡；該場未寫入，
#   重啟後仍排在佇列，每次都死在同一場 — 這些比賽永遠補不回。
#   修復 2 — 四個分支及執行器整體包上 try/except：手動模式例外照常拋出
#   (行為與舊版完全一致)；自動模式下錯誤寫入日誌、該場列入待手動處理清單、
#   自動繼續下一場 (把 V15.3 的失敗續傳精神延伸到例外崩潰)。
#   RerunException/StopException (Streamlit 內部控制流) 會先放行，不受影響。
#
#   根因 3 — 自動輸入只存在於啟動裝置的瀏覽器 session：分頁關閉/電腦休眠/
#   網絡中斷/容器重啟都會令運行死亡，只能回到原裝置重按「開始」。
#   修復 3 — 進度橫幅偵測到「active 但逾 5 分鐘無更新」時，提供一鍵
#   「本裝置接手續傳」：按狀態檔記錄的輪次在本裝置重建佇列 (已記錄/已結算
#   自動略過，與開始時同一套重複檢查)，從中斷處繼續。接手以 sid (session
#   標記) 互斥：接手後原裝置偵測到狀態檔 sid 不符會自動停止，兩邊不會同時
#   寫入；重複注單防護 (同比賽+日期+盤口+方向+盤口線+賠率) 仍然生效。
#
#   風險評估：零。三項修復全部在「通訊層」與「錯誤處理層」：GitHub 請求參數、
#   例外捕捉、新按鈕。學習引擎 (V9/V10/V11)、結算、風控、投注建議的計算
#   路徑與公式一字未改；手動模式行為與舊版完全一致。
# =============================================================================
# ==============================================================================
# V15.6 數據庫即時預覽效能修復 (純顯示層優化，零影響學習/分析/預測/投注建議)
#
#   背景 (2026-11-14)：數據庫累積至數百筆注單後，「🔍 數據庫即時線上預覽與管理」
#   載入極慢，甚至瀏覽器無響應後自動刷新頁面。經逐行排查，成因有三，全部是
#   「顯示與傳送層」問題，與數據內容、學習引擎或任何計算邏輯無關：
#     1. 預覽表格把整個數據庫全部 ~60 欄原封不動序列化傳送瀏覽器，包括
#        Home/Away_Recent_Matches、H2H_Records、Home/Away_League_Stats、
#        Bookmaker_Odds、HKJC_Extra_Odds、Odds_History 等 JSON 巨欄
#        (每行數十 KB)，序列化後可達數十 MB，websocket 傳輸及瀏覽器渲染
#        皆超出負荷 → 連線逾時 → Streamlit 前端自動重連刷新 (彈窗被關掉)。
#     2. 搜尋框每輸入一個字，舊碼對整個數據庫 (連 JSON 巨欄) 做 astype(str)
#        全欄字串比對，每次重跑都要幾秒。
#     3. CLV 欄每次重繪都對全部注單逐行 json.loads 解析 Odds_History，無快取。
#
#   修復 (只改「顯示與傳送」，完全不觸碰任何數據寫入路徑或計算邏輯)：
#     1. 預設只傳送輕量顯示欄 (剔除 8 個 JSON 巨欄)，傳送量縮小 90%+；
#        需要原始欄位時可勾選「顯示全部欄位」回到舊版完整表格 (行為不變)。
#     2. 搜尋只比對輕量文字欄 (ID/日期/狀態/聯賽/球隊/盤口/選項/賽果/半場比分/
#        Tipsme 編號)，涵蓋所有主要搜尋用途；勾選「顯示全部欄位」時自動
#        擴展至全欄搜尋 (與舊版完全一致)。
#     3. CLV 計算改用內容簽名快取 (C 速度雜湊 Bet_Type/Selection/Initial_Line/
#        Initial_Odds/Odds_History 五欄 + ID 順序)：數據庫內容不變時直接重用，
#        不再每次逐行 JSON 解析；內容有任何改動即自動重算，數值保證一致。
#     4. 表格加高度上限 (620px) 及「顯示筆數」選擇 (預設最新 500 筆)；
#        盈虧指標與下載報表永遠計算/包含全部符合筆數，數值與舊版完全一致。
#
#   風險評估：零。學習引擎 (V9/V10/V11)、自動導入、結算、風控、投注建議
#   全部讀取 st.session_state.df_db 原始數據，本修改不刪除、不改寫任何數據，
#   亦不改變任何計算公式 — 只有預覽畫面「傳送哪些欄位、幾筆」改變了。
# =============================================================================
# ==============================================================================
# V15.5 模擬注自動預選修復 (自動導入不再整場跳過)
#
#   背景 (2026-11-14)：用家啟動挪威聯賽第 18-26 輪自動輸入 (66 場)，只有 3 場
#   記錄了 4 張注單，其餘 63 場全部顯示「分析完成：0 個實注建議 / 0 個系統注項
#   (含模擬注) → 本場沒有可記錄的注項，跳到下一場」。但同一批比賽的分析畫面
#   明明顯示「📝 模擬首選 (注碼 $0，只供追蹤)」— 即模型有傾向、盤口有效，
#   卻沒有自動選入「系統投注」的預選清單。
#
#   根因：v11_auto_sys_picks 的「每種盤口自動預選一注 (無 ✅ 建議時選 $0 模擬注)」
#   受側邊欄「系統自動預選每種盤口」開關 (v11_auto_sys) 控制；該開關一旦關閉
#   會被永久儲存 (v10_save_settings)。開關關閉時 auto_sys 只餘 ✅ 實注建議 —
#   未通過驗證的聯賽/策略 (只剩 📝 模擬注) 便整場「沒有可記錄的注項」被跳過，
#   系統完全得不到學習數據。自動導入歷史賽事的目的正是零成本累積學習樣本，
#   此開關不應令自動導入空手而回。
#
#   修復：
#   1. (核心) 自動導入模式 (V14.12 自動輸入進行中) 強制啟用自動預選：分析結果的
#      auto_sys 一律按「每種盤口一注 (✅ 實注或 $0 模擬注)」計算，不受側邊欄
#      開關影響；開關關閉時會在日誌提示。手動模式行為完全不變 (仍尊重開關)。
#   2. 自動執行器 BET 步驟及投注畫面的預選清單：auto_sys 及實注建議皆空時，
#      以「📝 模擬首選」為後備，確保分析有產生候選就不會整場跳過。
#   3. 日誌「分析完成」一行現在顯示「含 N 個 $0 模擬注」，讓用家清楚看到
#      每場記錄的注項構成。
#   4. 自動模式下「本場沒有可記錄的注項」跳過時也會同步進度到 auto_status.csv
#      (跨裝置進度橫幅不會漏掉被跳過的場次)。
#
#   風險評估：模擬注注碼固定 $0 (v11_is_real_pick 以外一律 $0)，不會動用真實
#   資金；重複注單防護 (同比賽+日期+盤口+方向+盤口線+賠率) 仍然生效，重跑
#   自動導入不會產生重複記錄。被跳過的 63 場因沒有寫入任何注單，重跑自動
#   導入即會全部補回。
