# V15.2 重複注單清理 + 賽程譯名比對修復 + 驗證面板強化
#
#   1. 一次性清理 K-League 重複注單 (V15.2 self-repair)：
#      2026-11-11 自動導入時，v14_find_duplicate_match 以賽程頁譯名 (浦项铁人/濟州聯SK FC)
#      比對資料庫譯名 (浦項制鐵/濟州SK) 兩邊皆不吻合，誤判「浦項制鐵 vs 濟州SK (2026-11-01)」
#      未記錄，於已記錄的用家注單 (B202611012256560 入球大小 Under 2.5) 之外，重複寫入
#      系統模擬注 B202611111218360 (入球大小 Over 2.5，$0 模擬注)。本版於啟動時自動
#      刪除該重複注單 (ID + 球隊 + 日期 + 盤口四重防呆)，並同步雲端資料庫。
#
#   2. BUG FIX 賽程譯名比對：v14_find_duplicate_match 新增球隊譯名別名表
#      (_V14_NAME_ALIASES)，將賽程頁簡體/異體譯名正規化為資料庫譯名後才比對
#      (浦项铁人→浦項制鐵、富川FC→FC富川、濟州聯SK FC→濟州SK 等)。此後自動導入
#      不會再因譯名差異把已記錄賽事誤判為未記錄而重複寫入。
#
#   3. 「🔍 數據驗證」面板新增兩項檢查：
#      a) 同場重複注單：同一比賽 (聯賽+對賽+日期+盤口+選項+盤口線) 出現兩張相同注單時列出，
#         供用家核實是否重複入帳 (即場注及不同盤口線/不同選項的正常加注不會誤報)；
#      b) 無 Tipsme 編號注單統計：顯示沒有 Tipsme_Match_ID 的注單數 (手動記錄)，
#         提醒該批注單無法以比賽 ID 自動核對 (只統計，不列入問題清單)。
#
# ==============================================================================
# V15.1 賽程狀態誤報修復 + K-League 待結算注單自動修復 + 數據驗證
#
#   1. BUG FIX 賽程狀態誤報「✅ 賽果已結算」：
#      v14_find_duplicate_match 的名稱比對 (V14.11 起) 是「完全同名 OR (單邊吻合 AND 同日期)」，
#      完全同名一項沒有日期約束。南韓聯賽 12 隊小聯賽一季同一對組合對賽 3-4 次，
#      未來輪次 (如 R36 全北汽車 vs FC首爾 11-21) 與資料庫舊輪次 (R28 同組合 08-01) 隊名完全相同，
#      於是整季已導入後，大部分未來賽事被誤判為已結算。而部分場次 (如 浦項制鐵) 因賽程頁譯名
#      (浦项铁人) 與資料庫譯名不同，比對不到反而正確顯示未記錄 — 這就是「有時誤報、有時正常」的原因。
#      V15.1：兩種名稱比對都必須「日期相同」才視為同一場 (_same_date & (...))。
#      已用真實數據庫驗證：R36/R37/R38 全部未開賽場次不再誤報 (12/12 場正確顯示未記錄)，
#      而已導入的 137 場南韓賽事仍正確顯示已結算。
#
#   2. K-League 待結算注單自動修復 (V15.1 self-repair)：
#      2026-11-11 自動導入中途中斷，令「FC首爾 vs FC安養 (05-05)」2 張注單停留 Open
#      (讓球 Away -0.75 @2.09 / 入球大小 Over 2.50 @1.80，皆 $0 模擬注)。真實賽果
#      經 Tipsme API 核實 (Score/match/105841)：全場 0-0、半場 0-0、角球 3-3、紅 1-1、黃 2-2。
#      結算結果：讓球 Away -0.75 → diff = 0-0-(-0.75) = +0.75 ≥0.5 → 全贏 +0.09單位；
#      入球大小 Over 2.50 → diff = 0-2.5 = -2.5 → 全輸 -1單位。兩注 $0 模擬注，無實際金額影響。
#      修復為一次性 (ID 比對 + 球隊名防呆)，與 V13.1 self-repair 同一機制。
#
#   3. 新增「🔍 數據驗證」面板 (結算與管理頁頂部)：
#      隨時對整個雲端數據庫做離線完整性檢查 (V15.2 verify_db_integrity)：
#      a) 已結算注單：Result_Label / Unit_Profit / System_Profit / Payout 與
#         calculate_settlement 重算結果比對 (讓球/入球大小/角球大小全盤口，含贏半/輸半/走盤)；
#      b) Open 注單：列出並提醒處理；
#      c) 結構檢查：Half_Score > 全場比數、缺角球/紅牌數據、同場重複注單偵測。
#      全部通過時顯示「✅ 數據完整無誤」，有問題時列出明細。只驗證、不自動改動數據。
#
# ==============================================================================
# V14.12 自動導入歷史賽事 (全自動批次：填充 → 分析 → 系統投注 → 結算 → 下一場)
#
#   貼上 Tipsme 聯賽賽程連結並讀取賽程後，在「自動導入歷史賽事」面板選擇輪次
#   (可選一輪或多輪，例如第 4 輪或第 4-10 輪)，按「開始」後系統會自動處理所選
#   輪次內所有「已完場且未記錄」的比賽，每場依序執行：
#     1. 填充此場 — tipsme_auto_fill (賽事資料、排名、近況、盤口賠率全自動)
#     2. 驗證填充資料 — 比賽 ID 與賽程一致；已記錄/已結算的比賽自動跳過
#     3. 賽前數據分析 — 與手動按下「🚀 賽前數據分析執行」完全同一邏輯
#     4. 系統投注 — 自動提交 v11_auto_sys_picks 的項目 (實注或 $0 模擬注，
#        與手動流程的預選完全一致；用家投注一律 $0，過往賽事毋須人手下注)
#     5. 自動讀取賽果 — 先用注單記錄的比賽 ID 讀取，並與賽程頁賽果交叉核對
#        (全場比數/角球/紅牌不符即自動暫停，絕不結算錯誤數據)
#     6. 確定結算 — 與手動結算同一邏輯，結算後自動學習 (v14_warm_engines)
#   全部輪次完成後自動停止，並顯示完整執行日誌。
#
#   實現方式：狀態機存於 st.session_state['v15_auto']，每次 Streamlit 重繪執行
#   一步 (v15_auto_executor)；四個關鍵按鈕 (分析/投注/讀取賽果/結算) 加上
#   自動觸發條件 _v15_on(step)，與手動點擊走完全相同的程式碼路徑，不會分叉。
#
# ==============================================================================
# V14 注碼與風控修正 (基於 V13 完整程式碼)
#
# 問題 (V13)：
#   1. 「最低建議注碼」所有盤口共用一個數值，令入球/角球的 Kelly 注碼 (例如 $20)
#      被強制湊大到 $200 — 與「根據預測勝率及本金精準下注」的原則矛盾。
#   2. 舊版「讓球最低 $200」規則把 EV 偏低的讓球注強制升至 $200，放大邊緣投注虧損。
#   3. 未通過樣本外驗證的盤口一律 $0 模擬注，正 ROI 的盤口也無法實注。
#
# V14 修正：
#   A. 馬會最低注額改為「分盤口下限過濾」：讓球 $200、其他盤口 $10 (可於側邊欄調整)。
#      Kelly 注碼 ≥ 下限 → 按精準 Kelly 注碼實注；< 下限 → $0 模擬注，絕不強制湊大。
#      (強制把 $140 的讓球注湊到 $200 = 用 1.43 倍風險賭同一個優勢，長期必然放大虧損。)
#   B. 新增「試注層 (半注 Kelly)」：策略未完全通過驗證 (≥50 注、ROI ≥ +2%、前後兩段皆賺)，
#      但已有初步正回報 (≥30 注、ROI ≥ +1%、前後兩段未同時虧損) 時，以半注 Kelly 實注，
#      狀態顯示「✅ 試注」。門檻全部可在側邊欄調整。
#   C. 注碼 $0 時顯示具體原因 (Kelly 注碼低於馬會最低注額 / 策略未驗證)，方便判斷
#      是「本金不足」還是「無優勢」。
#
# 所需本金參考 (Kelly 0.25、讓球 EV 4-5% @ 賠率 ~1.9)：
#   Kelly 注碼 = 本金 × 0.25 × EV/(賠率−1) ≥ $200 → 本金 ≥ 約 $14,400 (EV 5%) ~ $18,000 (EV 4%)。
#   建議系統本金 ≥ $20,000，讓球盤的合格建議才能自然達到 $200；入球/角球 $10 起，本金 $1,000 已足夠。
#
# =============================================================================
# V14.1 效能與流程改善 (V14 基礎上的修正，完全不影響學習及分析能力)
#
# 問題 (V14)：每結算一場，模型快取即被清空，下一場賽前分析都要由零重新訓練
#   V9 (約 8 秒) + V10 (約 9 秒) + V11 競技場 (約 13 秒)，加上分析頁渲染，
#   令每場流程長達 1 分 20 秒左右。數據越多會越慢，但主因是「每場都重訓」而非數據量。
#
# V14.1 修正：
#   1. 模型快取改以「數據簽名」為鍵 (已結算注單數 ÷ 5)：結算後若簽名不變，
#      下一場賽前分析直接命中快取，即時完成 (~1 秒)；每累積 5 場新賽果才重訓一次。
#      學習結果與逐場重訓完全一致 (模型只取決於已結算注單內容，時鐘從頭訓練)。
#   2. 結算後自動預先學習：每 5 場的重訓移到結算步驟進行 (有進度提示)，
#      不再發生在下一場賽前分析的關鍵路徑上。
#   3. 新增「賽程連結模式」：貼上 Tipsme 聯賽賽程連結即可一次讀取整季全部輪次
#      (賽程頁已內嵌整季比賽數據)，按輪次選比賽、逐場一鍵填充，
#      不用再逐場複製比賽鏈結；已完場比賽附賽果，可直接核對結算。
#   4. 側邊欄「重新訓練」按鈕改為清除全部模型快取 (含簽名快取)，行為不變。
#
# =============================================================================
# V14.2 角球停用與面板搬移
#
#   1. 新增「🚫 停用角球大小」設定 (側邊欄，預設開啟)：角球樣本已達統計顯著虧損
#      (580 注、每注 −15.3 單位、95% 信賴區間全為負)，繼續記錄只會令模型學到雜訊。
#      開啟後角球大小不參與自動預選、模擬注及記錄；分析表仍顯示「⏸ 角球已停用」
