try:
    from sqlalchemy import create_engine
    import sqlalchemy
    HAS_SQLALCHEMY = True
except ImportError:
    HAS_SQLALCHEMY = False


@st.cache_resource(ttl=None, show_spinner=False)
def _v163_sql_engine():
    """V16.3.1：全 app 共用一個 SQL 引擎 (單例 + pool_pre_ping + 連線回收)。

    背景 (2026-11-18 用家實測事故)：舊代碼每次讀/寫都 create_engine 新引擎，
    各引擎自帶連接池且從不 dispose — 長時間運行的 session (尤其 V16 CLV 每 5
    分鐘快照) 下連線不斷累積，Supabase 連接數上限被吃光 → 間歇性
    「SQL 資料庫儲存失敗」→ 側邊欄紅色「雲端同步已連續失敗」警告，最嚴重時
    用家刪注後刪除結果只存在容器，容器重建 (部署新版) 後已刪注單「復活」。

    修正：全部 SQL 存取改用本單例引擎；pool_pre_ping 令斷線/過期連線自動
    偵測重建，pool_recycle 定期回收閒置連線。無 SQL 設定 → 回傳 None
    (呼叫端照舊跳過)。"""
    try:
        if not (HAS_SQLALCHEMY and _has_secret("DB_URL") and st.secrets["DB_URL"]):
            return None
        return create_engine(st.secrets["DB_URL"], pool_pre_ping=True, pool_recycle=1800)
    except Exception:
        return None

# =============================================================================
# V16.4 刪除墓碑 (tombstone) — 刪注持久化的統一修復 — 2026-11-18
# =============================================================================
V164_TOMB_TABLE = 'football_bets_deleted'

def _v164_tomb_read():
    """V16.4：讀取全部刪除墓碑 ID (SQL 表，每次即時讀取 — 任何裝置的刪除
    即時對所有裝置生效)。表不存在/讀取失敗 → 空集 (不影響任何既有行為)。

    背景：刪注復活有三條獨立鏈路，V16.3.1 只堵了一條 —
    1. 差量備份檔 (GitHub) 以 ID 聯集合併、永不遺忘已刪 ID；GitHub 上傳在
       用家網絡長期失敗 (實測連續 5 次) → 備份檔成為「殭屍」：每次載入
       merge_pending_on_load 把已刪注單合併回 session 並回寫 SQL → 復活；
    2. 主裝置長開 session 記憶體仍留有已刪注單，_v161_refresh_db_from_sql
       的 ID 聯集合併「本機獨有列全保留」令它們永不消失；
    3. 兩裝置同時儲存同一批變動列時 DELETE+INSERT 競態令 SQL 出現同 ID
       重複列 (用家跟投分頁 StreamlitDuplicateElementKey 崩潰的源頭)。
    墓碑 = 已刪 ID 的持久清單 (SQL 表，冪等)：載入/合併/刷新一律過濾，
    寫入一律過濾 — 三條鏈路一次堵死。"""
    try:
        engine = _v163_sql_engine()
        if engine is None:
            return set()
        from sqlalchemy import text
        with engine.connect() as conn:
            _rows = conn.execute(text(f'SELECT "id" FROM "{V164_TOMB_TABLE}"')).fetchall()
        return {str(r[0]) for r in _rows if r[0] is not None and str(r[0]).strip()}
    except Exception:
        return set()

def _v164_drop_tombs(df):
    """V16.4：從 df 過濾已墓碑化的列 (任何載入/合併/刷新點統一使用)。"""
    try:
        if df is None or df.empty or 'ID' not in df.columns:
            return df
        _t = _v164_tomb_read()
        if not _t:
            return df
        return df[~df['ID'].astype(str).isin(_t)]
    except Exception:
        return df

